import { Router } from 'express';
import { documentController, invoiceController, quoteController, timeController } from '../controllers/business.controller.js';
import { asyncHandler } from '../middleware/async-handler.js';
import { requireAuth } from '../middleware/auth.middleware.js';
export const documentRouter = Router();
export const timeRouter = Router();
export const quoteRouter = Router();
export const invoiceRouter = Router();
documentRouter.use(requireAuth);
documentRouter.get('/', asyncHandler(documentController.list));
documentRouter.post('/', asyncHandler(documentController.create));
documentRouter.patch('/:id', asyncHandler(documentController.update));
documentRouter.post('/:id/revisions', asyncHandler(documentController.revise));
documentRouter.delete('/:id', asyncHandler(documentController.delete));
timeRouter.use(requireAuth);
timeRouter.get('/', asyncHandler(timeController.list));
timeRouter.post('/', asyncHandler(timeController.create));
timeRouter.patch('/:id', asyncHandler(timeController.update));
timeRouter.post('/timer', asyncHandler(timeController.startTimer));
timeRouter.post('/:id/stop', asyncHandler(timeController.stopTimer));
timeRouter.delete('/:id', asyncHandler(timeController.delete));
quoteRouter.use(requireAuth);
quoteRouter.get('/', asyncHandler(quoteController.list));
quoteRouter.get('/:id', asyncHandler(quoteController.get));
quoteRouter.post('/', asyncHandler(quoteController.create));
quoteRouter.patch('/:id', asyncHandler(quoteController.update));
quoteRouter.post('/:id/convert-to-invoice', asyncHandler(quoteController.convertToInvoice));
quoteRouter.get('/:id/pdf', asyncHandler(quoteController.pdf));
quoteRouter.delete('/:id', asyncHandler(quoteController.delete));
invoiceRouter.use(requireAuth);
invoiceRouter.get('/', asyncHandler(invoiceController.list));
invoiceRouter.get('/:id', asyncHandler(invoiceController.get));
invoiceRouter.post('/', asyncHandler(invoiceController.create));
invoiceRouter.patch('/:id', asyncHandler(invoiceController.update));
invoiceRouter.put('/:id', asyncHandler(invoiceController.update));
invoiceRouter.post('/:id/send', asyncHandler(invoiceController.send));
invoiceRouter.post('/:id/mark-paid', asyncHandler(invoiceController.markPaid));
invoiceRouter.post('/:id/mark-overdue', asyncHandler(invoiceController.markOverdue));
invoiceRouter.post('/:id/void', asyncHandler(invoiceController.void));
invoiceRouter.get('/:id/pdf', asyncHandler(invoiceController.pdf));
invoiceRouter.delete('/:id', asyncHandler(invoiceController.delete));
